 * Author: @jiuyi0204
 * Usage: 作者 @jiuyi0204：未经作者明确许可，禁止二次修改、二次上传、转载、重新打包或冒名发布；第三方字体、图片、图标和代码继续遵守各自原许可证。
 * Third-party: Zhuque Fangsong remains under SIL Open Font License 1.1.
 */

/* ===== src/kernel/state-protection.css ===== */
/* Seka kernel / bounded functional and state protection. */
#chat .mes_block,
#send_form,
#nonQRFormItems,
#send_textarea {
    min-width: 0;
}

#chat .mesAvatarWrapper::before {
    pointer-events: none;
}

#left-nav-panel,
#rm_api_block,
#AdvancedFormatting,
#WorldInfo,
#user-settings-block,
#Backgrounds,
#rm_extensions_block,
#PersonaManagement,
#right-nav-panel {
    box-sizing: border-box;
}

::-webkit-scrollbar {
    display: none !important;
}

* {
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}

/* ===== src/tokens.css ===== */
/* Seka / design tokens and shared font mapping. Window rules remain independently scoped. */
@font-face {
    font-family: "Zhuque Fangsong";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/zhuquefangsong/zhuquefangsong.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    --seka-avatar-size: 78px;
    --seka-avatar-ornament-size: 116px;
    --seka-reading-width: 78ch;
    --seka-control-height: 38px;
    --seka-coral: #f2abaf;
    --seka-peach: #f5ccc6;
    --seka-paper: #fbf2e9;
    --seka-blue: #b8c9e7;
    --seka-ink: #40506b;
    --seka-muted: #7b7380;
    --seka-line: rgba(64, 80, 107, 0.22);
    --seka-line-strong: rgba(64, 80, 107, 0.42);
    --seka-coral-wash: rgba(242, 171, 175, 0.22);
    --seka-blue-wash: rgba(184, 201, 231, 0.28);
    --seka-paper-glass: rgba(251, 242, 233, 0.94);
    --seka-radius-small: 8px;
    --seka-radius-medium: 14px;
    --seka-radius-large: 20px;
    --seka-shadow-soft: 0 10px 28px rgba(64, 80, 107, 0.12);
    --seka-shadow-lift: 0 8px 18px rgba(242, 171, 175, 0.16), 0 2px 8px rgba(64, 80, 107, 0.08);
    --seka-font: "Zhuque Fangsong", "Source Han Serif SC", "Noto Serif SC", "Songti SC", STSong, serif;
    --seka-paper-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/8579d8e26f016b37cf542eebe6fdc872c328fddd/assets/Seka/seka-paper-texture.png");
    --seka-user-ornament: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/8579d8e26f016b37cf542eebe6fdc872c328fddd/assets/Seka/seka-avatar-user-ornament.png");
    --seka-assistant-ornament: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/8579d8e26f016b37cf542eebe6fdc872c328fddd/assets/Seka/seka-avatar-seka-ornament.png");
}

body {
    color: var(--seka-ink);
    font-family: var(--seka-font);
}

#chat,
#top-bar,
#send_form,
#left-nav-panel,
#rm_api_block,
#AdvancedFormatting,
#WorldInfo,
#user-settings-block,
#Backgrounds,
#rm_extensions_block,
#PersonaManagement,
#right-nav-panel,
.popup,
#completion_prompt_manager_popup,
#toast-container {
    font-family: var(--seka-font);
}

#chat ::selection,
#send_form ::selection,
#left-nav-panel ::selection,
#rm_api_block ::selection,
#AdvancedFormatting ::selection,
#WorldInfo ::selection,
#user-settings-block ::selection,
#Backgrounds ::selection,
#rm_extensions_block ::selection,
#PersonaManagement ::selection,
#right-nav-panel ::selection,
.popup ::selection {
    color: var(--seka-ink);
    background: rgba(184, 201, 231, 0.62);
}

/* ===== src/chat-layout.css ===== */
/* Seka / one approved chat shell. Long-form typography lives in full-text.css. */
#chat {
    gap: 14px;
    padding: 18px clamp(10px, 2vw, 28px) 22px;
    scroll-padding-block: 20px;
}

#chat > .mes {
    flex: 0 0 auto;
}

#chat .mesAvatarWrapper {
    flex: 0 0 calc(var(--seka-avatar-size) + 10px);
    min-width: calc(var(--seka-avatar-size) + 10px);
    min-height: calc(var(--seka-avatar-size) + 10px);
}

#chat .mes_block {
    min-width: 0;
}

#chat {
    color: var(--seka-ink);
    background-color: var(--seka-paper);
    background-image: linear-gradient(rgba(251, 242, 233, 0.84), rgba(251, 242, 233, 0.84)), var(--seka-paper-image);
    background-repeat: repeat;
    background-size: auto, 512px 512px;
    border: 1px solid var(--seka-line);
    border-radius: var(--seka-radius-large) var(--seka-radius-large) 0 0;
    box-shadow: var(--seka-shadow-soft);
    text-shadow: none;
}

#chat .mes {
    isolation: isolate;
    color: var(--seka-ink);
    background-color: rgba(251, 242, 233, 0.9);
    background-image: linear-gradient(rgba(251, 242, 233, 0.83), rgba(251, 242, 233, 0.83)), var(--seka-paper-image);
    background-repeat: repeat;
    background-size: auto, 512px 512px;
    border: 1px solid var(--seka-line);
    border-radius: var(--seka-radius-large);
    box-shadow: 0 5px 16px rgba(64, 80, 107, 0.08);
    padding: 18px 18px 16px;
}

#chat .mes[is_user="true"] {
    background-color: rgba(245, 204, 198, 0.72);
    background-image: linear-gradient(115deg, rgba(245, 204, 198, 0.78), rgba(251, 242, 233, 0.91) 52%, rgba(251, 242, 233, 0.96)), var(--seka-paper-image);
    border-left: 4px solid var(--seka-coral);
}

#chat .mes[is_user="false"]:not([is_system="true"]) {
    border-right: 4px solid var(--seka-blue);
}

#chat .mes[is_system="true"] {
    background-color: rgba(184, 201, 231, 0.2);
    background-image: none;
    border-style: dashed;
}

#chat .mesAvatarWrapper {
    position: relative;
    z-index: 2;
    margin: 1px 14px 0 0;
    overflow: visible;
}

#chat .mesAvatarWrapper::before {
    content: "";
    position: absolute;
    width: var(--seka-avatar-ornament-size);
    height: var(--seka-avatar-ornament-size);
    left: calc((var(--seka-avatar-size) - var(--seka-avatar-ornament-size)) / 2 + 2px);
    top: calc((var(--seka-avatar-size) - var(--seka-avatar-ornament-size)) / 2 + 2px);
    z-index: 3;
    pointer-events: none;
    background-position: center;
    background-repeat: no-repeat;
    background-size: contain;
}

#chat .mes[is_user="true"] .mesAvatarWrapper::before {
    background-image: var(--seka-user-ornament);
}

#chat .mes[is_user="false"]:not([is_system="true"]) .mesAvatarWrapper::before {
    background-image: var(--seka-assistant-ornament);
}

#chat .mes .avatar,
#chat .mes .avatar img {
    width: var(--seka-avatar-size);
    height: var(--seka-avatar-size);
    border-radius: 14px;
}

#chat .mes .avatar {
    position: relative;
    z-index: 2;
    margin: 4px;
    background: var(--seka-paper);
    border: 2px solid var(--seka-coral);
    box-shadow: 0 6px 16px rgba(64, 80, 107, 0.14);
}

#chat .mes[is_user="false"]:not([is_system="true"]) .avatar {
    border-color: var(--seka-blue);
}

#chat .mes[is_user="false"]:not([is_system="true"]) .mesAvatarWrapper {
    order: 2;
    margin-right: 0;
    margin-left: 16px;
}

#chat .mes[is_user="false"]:not([is_system="true"]) .mes_block {
    order: 1;
    padding-left: 0;
    padding-right: 10px;
}

#chat .mes_block {
    padding-left: 10px;
}

#chat .ch_name {
    min-height: 28px;
    color: var(--seka-ink);
    border-bottom: 1px solid var(--seka-line);
    padding-bottom: 7px;
    margin-bottom: 4px;
}

#chat .name_text {
    color: var(--seka-ink);
    font-family: var(--seka-font);
    font-size: clamp(1.05rem, 1.6vw, 1.28rem);
    font-weight: 400;
    letter-spacing: 0.045em;
}

#chat .mes[is_user="true"] .name_text {
    color: #a85e68;
}

#chat .mes[is_user="false"]:not([is_system="true"]) .name_text {
    color: #526f9f;
}

#chat .timestamp,
#chat .mes_timer,
#chat .mesIDDisplay,
#chat .tokenCounterDisplay {
    color: var(--seka-muted);
    font-size: 0.72rem;
    letter-spacing: 0.04em;
    opacity: 0.86;
}

#chat .mes_reasoning {
    color: var(--seka-ink);
    font-family: var(--seka-font);
    font-weight: 400;
    font-size: clamp(1rem, 1.15vw, 1.08rem);
    line-height: 1.9;
    text-wrap: pretty;
    background: rgba(251, 242, 233, 0.62);
    border-left-color: var(--seka-blue);
}

#chat .mes_buttons,
#chat .extraMesButtons,
#chat .mes_edit_buttons {
    color: var(--seka-muted);
    filter: none;
}

#chat .mes_button,
#chat .extraMesButtons > div,
#chat .mes_edit_buttons .menu_button {
    color: var(--seka-muted);
    background: transparent;
    border: 0;
    border-radius: 0;
    filter: none;
    opacity: 0.64;
    transition: color 160ms ease, opacity 160ms ease, transform 160ms ease;
}

#chat .mes_button:hover,
#chat .extraMesButtons > div:hover,
#chat .mes_edit_buttons .menu_button:hover {
    color: var(--seka-ink);
    opacity: 1;
    transform: translateY(-1px);
}

#chat .mes_button:focus-visible,
#chat .extraMesButtons > div:focus-visible,
#chat .mes_edit_buttons .menu_button:focus-visible {
    outline: 2px dashed var(--seka-ink);
    outline-offset: 3px;
    opacity: 1;
}

#chat .mes_reasoning_details {
    background: linear-gradient(135deg, rgba(245, 204, 198, 0.28), rgba(251, 242, 233, 0.90) 54%, rgba(184, 201, 231, 0.24));
    border: 1px solid rgba(184, 201, 231, 0.62);
    border-radius: var(--seka-radius-medium);
    padding: 8px 12px;
}

#chat .mes_reasoning_header {
    color: var(--seka-ink);
    background-color: var(--seka-paper);
    background-image: linear-gradient(90deg, rgba(245, 204, 198, 0.76), rgba(251, 242, 233, 0.96) 52%, rgba(184, 201, 231, 0.58));
    border: 1px solid var(--seka-line-strong);
    box-shadow: 0 3px 9px rgba(64, 80, 107, 0.07);
    text-shadow: none;
}

#chat .mes_reasoning_header:hover,
#chat .mes_reasoning_details[open] .mes_reasoning_header,
#chat .mes_reasoning_details[data-state="thinking"] .mes_reasoning_header {
    background-image: linear-gradient(90deg, rgba(242, 171, 175, 0.84), rgba(251, 242, 233, 0.98) 50%, rgba(184, 201, 231, 0.72));
    border-color: rgba(64, 80, 107, 0.52);
}

#chat .mes_reasoning :not(pre) > code {
    color: #4f3e55;
    background: rgba(245, 204, 198, 0.58);
    border: 1px solid rgba(197, 117, 129, 0.36);
    text-shadow: none;
}

#chat .mes_reasoning pre {
    color: var(--seka-ink);
    background-color: #f9e8e3;
    background-image: linear-gradient(135deg, rgba(245, 204, 198, 0.62), rgba(251, 242, 233, 0.96) 58%, rgba(184, 201, 231, 0.28));
    border: 1px solid rgba(197, 117, 129, 0.38);
    border-radius: var(--seka-radius-small);
    text-shadow: none;
}

#chat .mes_reasoning pre code,
#chat .mes_reasoning pre code.hljs {
    color: var(--seka-ink);
    background: transparent;
    border: 0;
    border-radius: 0;
    text-shadow: none;
}

#chat .swipe_left,
#chat .swipe_right,
#chat .swipes-counter {
    color: var(--seka-muted);
    filter: none;
}

/* ===== src/full-text.css ===== */
/* Seka / long-form message typography only. */
#chat .mes_text {
    max-width: var(--seka-reading-width);
    margin-inline: auto;
    padding: 10px clamp(2px, 1.2vw, 16px) 14px;
    color: var(--seka-ink);
    font-family: var(--seka-font);
    font-weight: 400;
    font-size: clamp(1rem, 1.15vw, 1.08rem);
    line-height: 1.9;
    text-wrap: pretty;
}

#chat .mes[is_user="true"] .mes_text {
    max-width: 66ch;
    margin-inline: 0;
}

#chat .mes_text p {
    margin-block: 0.72em;
}

#chat .mes_text :where(ul, ol) {
    margin-block: 0.68em;
    padding-inline-start: 1.65em;
}

#chat .mes_text li {
    margin-block: 0.28em;
}

#chat .mes_text :where(h1, h2, h3, h4) {
    color: var(--seka-ink);
    font-family: var(--seka-font);
    font-weight: 400;
    line-height: 1.35;
    letter-spacing: 0.045em;
}

#chat .mes_text :where(h1, h2) {
    border-bottom: 2px solid var(--seka-coral);
    padding-bottom: 0.35em;
}

#chat .mes_text blockquote {
    color: #596680;
    background: linear-gradient(90deg, rgba(245, 204, 198, 0.34), rgba(251, 242, 233, 0.84) 64%, rgba(184, 201, 231, 0.24));
    border-left: 3px solid var(--seka-blue);
    border-radius: 0 var(--seka-radius-small) var(--seka-radius-small) 0;
    padding: 0.55em 0.9em;
}

#chat .mes_text :not(pre) > code {
    color: #4f3e55;
    background: rgba(245, 204, 198, 0.58);
    border: 1px solid rgba(197, 117, 129, 0.36);
    border-radius: var(--seka-radius-small);
    text-shadow: none;
}

#chat .mes_text pre {
    max-width: 100%;
    overflow-x: auto;
    padding: 0.8em 1em;
    color: var(--seka-ink);
    background-color: #f9e8e3;
    background-image: linear-gradient(135deg, rgba(245, 204, 198, 0.66), rgba(251, 242, 233, 0.97) 58%, rgba(184, 201, 231, 0.30));
    border: 1px solid rgba(197, 117, 129, 0.40);
    border-radius: var(--seka-radius-small);
    text-shadow: none;
}

#chat .mes_text pre code,
#chat .mes_text pre code.hljs,
#chat .mes_text pre .hljs {
    color: var(--seka-ink);
    background: transparent !important;
    background-image: none !important;
    border: 0;
    border-radius: 0;
    padding: 0;
    box-shadow: none;
    filter: none;
    text-shadow: none;
}

#chat .mes_text pre :where(code, .hljs, span) {
    text-shadow: none;
}

#chat .mes_text a {
    color: #8f5867;
    text-decoration-color: var(--seka-coral);
    text-underline-offset: 0.18em;
}

#chat .mes_text hr {
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--seka-coral), var(--seka-blue), transparent);
    opacity: 0.7;
}

#chat .mes_text table {
    display: block;
    max-width: 100%;
    overflow-x: auto;
    border-collapse: collapse;
    border: 1px solid var(--seka-line);
    border-radius: var(--seka-radius-small);
}

#chat .mes_text :where(th, td) {
    border: 1px solid var(--seka-line);
    padding: 0.5em 0.7em;
}

#chat .mes_text th {
    background: var(--seka-blue-wash);
    font-weight: 400;
}

#chat .mes_text img {
    max-width: 100%;
    height: auto;
    border-radius: var(--seka-radius-medium);
    box-shadow: 0 5px 16px rgba(64, 80, 107, 0.12);
}

/* ===== src/windows/topbar.css ===== */
/* W02 — shared top bar and exact nine native entries, unframed. */
#top-bar {
    background-color: var(--seka-paper-glass);
    background-image: linear-gradient(90deg, rgba(242, 171, 175, 0.1), transparent 30%, transparent 70%, rgba(184, 201, 231, 0.14));
    border-bottom: 1px solid var(--seka-line);
    box-shadow: 0 5px 18px rgba(64, 80, 107, 0.1);
}

#top-settings-holder {
    color: var(--seka-ink);
}

:where(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > .drawer-toggle {
    color: var(--seka-ink);
    background: transparent;
    border: 0;
    border-radius: 0;
    box-shadow: inset 0 -3px transparent;
    transition: color 160ms ease, opacity 160ms ease, transform 160ms ease, box-shadow 160ms ease;
}

:where(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > .drawer-toggle .drawer-icon {
    color: var(--seka-ink);
    filter: none;
    opacity: 0.82;
}

:where(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > .drawer-toggle:hover {
    color: #243a5b;
    transform: translateY(-1px) scale(1.05);
}

:where(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
):has(> .drawer-content.openDrawer) > .drawer-toggle {
    color: #243a5b;
    box-shadow: inset 0 -3px var(--seka-coral);
}

:where(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > .drawer-toggle:focus-visible,
:where(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > .drawer-toggle .drawer-icon:focus-visible {
    outline: 2px dashed var(--seka-ink);
    outline-offset: 3px;
}

:where(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > .drawer-toggle .drawer-icon.disabled,
:where(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > .drawer-toggle[aria-disabled="true"] {
    color: #9fabc0;
    opacity: 0.55;
}

/* ===== src/windows/input.css ===== */
/* W03 — chat input, menu, magic wand, send and stop controls. */
#send_form {
    color: var(--seka-ink);
    background: var(--seka-paper-glass);
    border: 1px solid var(--seka-line-strong);
    border-radius: 0 0 var(--seka-radius-large) var(--seka-radius-large);
    box-shadow: 0 -4px 18px rgba(64, 80, 107, 0.08), var(--seka-shadow-soft);
    text-shadow: none;
}

#nonQRFormItems {
    background: transparent;
}

#send_textarea {
    color: var(--seka-ink);
    caret-color: #9b5d69;
    background: rgba(255, 255, 255, 0.28);
    border-radius: var(--seka-radius-medium);
    font-family: var(--seka-font);
    font-weight: 400;
    line-height: 1.55;
    text-shadow: none;
}

#send_textarea::placeholder {
    color: var(--seka-muted);
    opacity: 0.7;
}

#send_form:has(#send_textarea:focus-visible) {
    border-color: var(--seka-ink);
    outline: 2px solid rgba(184, 201, 231, 0.72);
    outline-offset: 2px;
}

#options_button,
#extensionsMenuButton,
#send_but,
#mes_continue,
#mes_impersonate,
#mes_stop,
#send_form .mes_stop,
#rightSendForm .stscript_btn {
    color: var(--seka-ink);
    background: transparent;
    border: 0;
    border-radius: 0;
    box-shadow: none;
    filter: none;
    opacity: 0.82;
    transition: color 160ms ease, opacity 160ms ease, transform 160ms ease;
}

#options_button {
    color: #9b5d69;
}

#extensionsMenuButton {
    color: #627da7;
}

#send_but,
#mes_continue,
#mes_impersonate {
    color: var(--seka-ink);
}

#mes_stop,
#send_form .mes_stop {
    color: #b85862;
}

#options_button:hover,
#extensionsMenuButton:hover,
#send_but:hover,
#mes_continue:hover,
#mes_impersonate:hover,
#mes_stop:hover,
#send_form .mes_stop:hover,
#rightSendForm .stscript_btn:hover {
    color: #243a5b;
    opacity: 1;
    transform: translateY(-1px) scale(1.08);
    filter: none;
}

#options_button:focus-visible,
#extensionsMenuButton:focus-visible,
#send_but:focus-visible,
#mes_continue:focus-visible,
#mes_impersonate:focus-visible,
#mes_stop:focus-visible,
#send_form .mes_stop:focus-visible,
#rightSendForm .stscript_btn:focus-visible {
    outline: 2px dashed var(--seka-ink);
    outline-offset: 3px;
    opacity: 1;
}

#form_sheld[data-generating="true"] #send_form,
body[data-generating="true"] #send_form {
    border-color: rgba(184, 201, 231, 0.88);
