/* ===== src/windows/formatting.css ===== */
/* W06 — advanced response formatting. */
#AdvancedFormatting {
    color: var(--seka-ink);
    background-color: var(--seka-paper);
    background-image: linear-gradient(rgba(251, 242, 233, 0.89), rgba(251, 242, 233, 0.89)), var(--seka-paper-image);
    background-repeat: repeat;
    background-size: auto, 512px 512px;
    border: 1px solid var(--seka-line-strong);
    border-radius: var(--seka-radius-large);
    box-shadow: var(--seka-shadow-soft);
    text-shadow: none;
}

#AdvancedFormatting :where(h2, h3, h4, strong, label) {
    color: var(--seka-ink);
    font-family: var(--seka-font);
    font-weight: 400;
}

#AdvancedFormatting > .flex-container:first-child {
    border-bottom: 2px solid var(--seka-coral);
    padding: 5px 8px 10px;
}

#AdvancedFormatting :where(.inline-drawer-header, .range-block-title, .standoutHeader) {
    color: var(--seka-ink);
    background: linear-gradient(90deg, var(--seka-coral-wash), var(--seka-blue-wash));
    border: 1px solid var(--seka-line);
    border-radius: var(--seka-radius-small);
    padding: 7px 10px;
}

#AdvancedFormatting :where(input, select, textarea, .text_pole) {
    color: var(--seka-ink);
    background: rgba(255, 255, 255, 0.58);
    border: 1px solid var(--seka-line-strong);
    border-radius: var(--seka-radius-small);
    font-family: var(--seka-font);
    text-shadow: none;
}

#AdvancedFormatting :where(input, select, textarea, .text_pole):focus-visible {
    border-color: var(--seka-ink);
    outline: 2px solid rgba(242, 171, 175, 0.54);
    outline-offset: 1px;
}

#AdvancedFormatting input[type="radio"] {
    accent-color: #c57581;
}

/*
 * SillyTavern checkboxes use appearance:none and draw the real tick through
 * ::before. Rebuild that chain inside the confirmed AdvancedFormatting root
 * so checked and unchecked states remain distinct on the pale paper surface.
 */
#AdvancedFormatting input[type="checkbox"] {
    color: var(--seka-ink);
    background-color: #fffaf5;
    border: 1.5px solid #9b5d69;
    border-radius: 4px;
    box-shadow: inset 0 0 0 1px rgba(245, 204, 198, 0.42);
    filter: none;
}

#AdvancedFormatting input[type="checkbox"]::before {
    content: "";
    width: 0.65em;
    height: 0.65em;
    box-shadow: inset 1em 1em #fff7ed;
    clip-path: polygon(14% 44%, 0 65%, 50% 100%, 100% 16%, 80% 0%, 43% 62%);
    opacity: 1;
    transform: scale(0);
    transform-origin: bottom left;
    transition: var(--animation-duration) transform ease-in-out;
}

#AdvancedFormatting input[type="checkbox"]:checked {
    background-color: #9b5d69;
    border-color: #70445b;
    box-shadow: 0 0 0 2px rgba(242, 171, 175, 0.46);
}

#AdvancedFormatting input[type="checkbox"]:checked::before {
    transform: scale(1);
}

#AdvancedFormatting input[type="checkbox"]:focus-visible {
    outline: 2px solid var(--seka-blue);
    outline-offset: 2px;
}

#AdvancedFormatting input[type="checkbox"]:disabled:not(:checked) {
    background-color: #f1e3df;
    border-color: #b38a91;
    opacity: 0.78;
}

#AdvancedFormatting input[type="checkbox"]:disabled:checked {
    background-color: #765866;
    border-color: #5e4050;
    opacity: 0.78;
}

#top-settings-holder:has(#main_api option[value="openai"]:checked) #AdvancedFormatting [data-cc-null] {
    color: #6d5262;
    filter: none;
    opacity: 1;
}

#top-settings-holder:has(#main_api option[value="openai"]:checked) #AdvancedFormatting [data-cc-null] :where(input, select, textarea, .text_pole) {
    color: #6d5262;
    background-color: #f8e5e1;
    background-image: linear-gradient(90deg, rgba(245, 204, 198, 0.76), rgba(251, 242, 233, 0.98) 58%, rgba(184, 201, 231, 0.42));
    border-color: var(--seka-line-strong);
    box-shadow: none;
    filter: none;
    opacity: 1;
    text-shadow: none;
}

/* Official disabled controls add brightness(.5); keep the state but not the gray block. */
#AdvancedFormatting :where(input, select, textarea, .text_pole):disabled,
#AdvancedFormatting .disabled {
    color: #6d5262;
    background-color: #f5dfdb;
    border-color: rgba(155, 93, 105, 0.44);
    box-shadow: none;
    filter: none;
    opacity: 1;
    text-shadow: none;
}

/* The live prompt list is `#completion_prompt_manager`; the similarly named popup is only its editor. */
#completion_prompt_manager,
#completion_prompt_manager #completion_prompt_manager_list {
    color: var(--seka-ink);
    background-color: rgba(251, 242, 233, 0.98);
    filter: none;
    text-shadow: none;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    margin-block: 4px;
    color: var(--seka-ink);
    background-color: rgba(255, 255, 255, 0.62);
    border-color: var(--seka-line-strong);
    border-radius: var(--seka-radius-small);
    filter: none;
    opacity: 1;
    text-shadow: none;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:hover {
    color: var(--seka-ink);
    background-color: rgba(184, 201, 231, 0.30);
    border-color: var(--seka-blue);
}

#completion_prompt_manager .completion_prompt_manager_header,
#completion_prompt_manager .completion_prompt_manager_header_advanced,
#completion_prompt_manager .completion_prompt_manager_header_advanced span,
#completion_prompt_manager .completion_prompt_manager_header_advanced span.fa-solid,
#completion_prompt_manager .completion_prompt_manager_footer,
#completion_prompt_manager .completion_prompt_manager_footer .menu_button,
#completion_prompt_manager #completion_prompt_manager_list .prompt_manager_prompt_tokens,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: var(--seka-ink);
    filter: none;
    opacity: 1;
    text-shadow: none;
}

/* Precisely override the official `span span span` opacity and black drop-shadow. */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt > span > .prompt_manager_prompt_controls > span {
    color: var(--seka-ink);
    filter: none;
    opacity: 1;
    text-shadow: none;
    transition: none;
}

/*
 * These are icon nodes, not text buttons. The stable prompt-manager root and
 * same-node Font Awesome classes need the native icon family even when a
 * surrounding window applies the theme font. !important is limited to this
 * confirmed competing property so missing-glyph squares cannot win again.
 */
#completion_prompt_manager .completion_prompt_manager_footer > .menu_button.fa-solid,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name > .fa-solid,
#completion_prompt_manager #completion_prompt_manager_list .prompt_manager_prompt_controls > .fa-solid {
    font-family: var(--fa-style-family-classic, "Font Awesome 6 Free") !important;
    font-style: normal;
    font-variant: normal;
    font-weight: 900;
    line-height: 1;
    text-rendering: auto;
    -webkit-font-smoothing: antialiased;
    filter: none;
    opacity: 1;
    text-shadow: none;
}

/* Override the official white50a type-marker rule at its real specificity. */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name > .fa-solid {
    color: #765866;
    filter: none;
    opacity: 1;
    text-shadow: none;
}

#completion_prompt_manager .completion_prompt_manager_footer > .menu_button.fa-solid,
#completion_prompt_manager #completion_prompt_manager_list .prompt_manager_prompt_controls > .fa-solid {
    color: var(--seka-ink);
}

/* Empty placeholders keep grid alignment but must not look like mystery blocks. */
#completion_prompt_manager #completion_prompt_manager_list .prompt_manager_prompt_controls > span.fa-solid:empty[class="fa-solid"] {
    color: transparent;
    filter: none;
    text-shadow: none;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt[data-pm-enabled="false"],
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.disabled,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
    color: #765866;
    background-color: #f2ded9;
    border-color: rgba(155, 93, 105, 0.34);
    filter: none;
    opacity: 1;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled > span > .prompt_manager_prompt_controls > .prompt-manager-toggle-action {
    color: #765866;
    filter: none;
    opacity: 1;
    text-shadow: none;
}

#AdvancedFormatting :where(.text_muted, .toggle-description) {
    color: var(--seka-muted);
}

/* Checkbox descriptions are primary control labels, not generic muted small text. */
#AdvancedFormatting label.checkbox_label > input[type="checkbox"] + small {
    color: var(--seka-ink);
    filter: none;
    opacity: 1;
    text-shadow: none;
}

/* Preserve an explicit but readable disabled tier. */
