/* W08 — user settings and theme management. */
#user-settings-block {
    color: var(--seka-ink);
    background-color: var(--seka-paper);
    background-image: linear-gradient(rgba(251, 242, 233, 0.89), rgba(251, 242, 233, 0.89)), var(--seka-paper-image);
    background-repeat: repeat;
    background-size: auto, 512px 512px;
    border: 1px solid var(--seka-line-strong);
    border-radius: var(--seka-radius-large);
    box-shadow: var(--seka-shadow-soft);
    text-shadow: none;
}

#user-settings-block :where(h2, h3, h4, strong, label) {
    color: var(--seka-ink);
    font-family: var(--seka-font);
    font-weight: 400;
}

#user-settings-block > .flex-container:first-child {
    border-bottom: 2px solid var(--seka-coral);
    padding: 4px 8px 10px;
}

#user-settings-block :where(.inline-drawer-header, .range-block-title, .standoutHeader) {
    background: linear-gradient(90deg, var(--seka-coral-wash), var(--seka-blue-wash));
    border: 1px solid var(--seka-line);
    border-radius: var(--seka-radius-small);
    padding: 7px 10px;
}

/* Official 1.14 uses the more specific `#user-settings-block h4` gray gradient. */
#user-settings-block h4,
#user-settings-block .standoutHeader,
#user-settings-block .inline-drawer-toggle.inline-drawer-header {
    color: var(--seka-ink);
    background-color: var(--seka-paper);
    background-image: linear-gradient(90deg, rgba(242, 171, 175, 0.48), rgba(251, 242, 233, 0.94) 52%, rgba(184, 201, 231, 0.46));
    border-color: var(--seka-line-strong);
    text-shadow: none;
}

#user-settings-block :where(#UI-Theme-Block, [name="UserSettingsFirstColumn"], [name="UserSettingsSecondColumn"]) {
    background: rgba(255, 255, 255, 0.2);
    border-color: var(--seka-line);
    border-radius: var(--seka-radius-medium);
}

#user-settings-block :where(input, select, textarea, .text_pole) {
    color: var(--seka-ink);
    background: rgba(255, 255, 255, 0.58);
    border: 1px solid var(--seka-line-strong);
    border-radius: var(--seka-radius-small);
    font-family: var(--seka-font);
    text-shadow: none;
}

#user-settings-block :where(input, select, textarea, .text_pole):focus-visible {
    border-color: var(--seka-ink);
    outline: 2px solid rgba(242, 171, 175, 0.54);
    outline-offset: 1px;
}

#user-settings-block input[type="range"],
#user-settings-block input[type="radio"] {
    accent-color: #c57581;
}

/* SillyTavern draws checkboxes with appearance:none and a clipped ::before tick. */
#user-settings-block input[type="checkbox"] {
    color: var(--seka-ink);
    background-color: rgba(255, 252, 248, 0.96);
    border: 1.5px solid #9b5d69;
    box-shadow: inset 0 0 0 1px rgba(245, 204, 198, 0.34);
    filter: none;
}

#user-settings-block input[type="checkbox"]::before {
    box-shadow: inset 1em 1em #fffaf5;
    filter: none;
    opacity: 1;
}

#user-settings-block input[type="checkbox"]:checked {
    background-color: #a45f6d;
    border-color: #70445b;
    box-shadow: 0 0 0 2px rgba(242, 171, 175, 0.34);
}

#user-settings-block input[type="checkbox"]:checked::before {
    transform: scale(1);
}

#user-settings-block input[type="checkbox"]:focus-visible {
    outline: 2px solid var(--seka-blue);
    outline-offset: 2px;
}

#user-settings-block input[type="checkbox"]:disabled {
    border-color: rgba(112, 68, 91, 0.52);
    opacity: 0.68;
}

#user-settings-block :where(.menu_button, .right_menu_button, button) {
    color: var(--seka-ink);
    background: rgba(245, 204, 198, 0.28);
    border: 1px solid var(--seka-line);
    border-radius: var(--seka-radius-small);
    box-shadow: none;
    font-family: var(--seka-font);
}

#user-settings-block :where(.menu_button, .right_menu_button, button):hover {
    background: var(--seka-blue-wash);
    border-color: var(--seka-line-strong);
}

#user-settings-block :where(.menu_button, .right_menu_button, button):focus-visible {
    outline: 2px dashed var(--seka-ink);
    outline-offset: 2px;
}

#user-settings-block :where(small, .text_muted, .toggle-description) {
    color: var(--seka-muted);
}

