    border-radius: var(--seka-radius-small);
}

#options :where(.list-group-item, .menu_button, a):hover,
#extensionsMenu :where(.list-group-item, .menu_button, a):hover {
    background: var(--seka-blue-wash);
}

#toast-container > .toast {
    position: relative;
    color: var(--seka-ink);
    background-color: rgba(251, 242, 233, 0.97);
    background-image: none;
    border: 1px solid var(--seka-line-strong);
    border-left: 5px solid var(--seka-blue);
    border-radius: var(--seka-radius-medium);
    box-shadow: 0 12px 30px rgba(64, 80, 107, 0.2);
    font-family: var(--seka-font);
    padding-left: 48px;
    text-shadow: none;
}

#toast-container > .toast::before {
    content: "i";
    position: absolute;
    left: 17px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--seka-ink);
    font-family: Georgia, serif;
    font-size: 1.1rem;
    font-weight: 700;
}

#toast-container > .toast-success {
    border-left-color: #6f9b8f;
}

#toast-container > .toast-success::before {
    content: "✓";
    color: #496f67;
}

#toast-container > .toast-warning {
    border-left-color: #cf9b63;
}

#toast-container > .toast-warning::before {
    content: "!";
    color: #8f643e;
}

#toast-container > .toast-error {
    border-left-color: #b85862;
}

#toast-container > .toast-error::before {
    content: "×";
    color: #8f3f49;
}

#toast-container :where(.toast-title, .toast-message) {
    color: var(--seka-ink);
    text-shadow: none;
}

#toast-container .toast-close-button {
    color: var(--seka-ink);
    opacity: 0.72;
    text-shadow: none;
}

#toast-container .toast-progress {
    background: linear-gradient(90deg, var(--seka-coral), var(--seka-blue));
    opacity: 0.78;
}

/* ===== src/windows/mobile.css ===== */
/* W14 — mobile chat, drawers and transient interfaces. */
@media screen and (max-width: 1000px) {
    :root {
        --seka-avatar-size: 54px;
        --seka-avatar-ornament-size: 82px;
        --seka-reading-width: 100%;
    }

    #top-bar {
        border-radius: 0;
    }

    :where(
        #ai-config-button,
        #sys-settings-button,
        #advanced-formatting-button,
        #WI-SP-button,
        #user-settings-button,
        #backgrounds-button,
        #extensions-settings-button,
        #persona-management-button,
        #rightNavHolder
    ) > .drawer-toggle {
        min-width: 32px;
        min-height: 32px;
        transform: none;
    }

    #chat {
        gap: 9px;
        padding: 9px 6px 12px;
        border-radius: var(--seka-radius-medium) var(--seka-radius-medium) 0 0;
    }

    #chat .mes {
        position: relative;
        padding: 13px 9px 12px;
        border-radius: var(--seka-radius-medium);
    }

    #chat .mesAvatarWrapper {
        flex-basis: calc(var(--seka-avatar-size) + 6px);
        min-width: calc(var(--seka-avatar-size) + 6px);
        margin-right: 8px;
    }

    #chat .mes[is_user="false"]:not([is_system="true"]) .mesAvatarWrapper {
        position: absolute;
        inset-block-start: 13px;
        inset-inline-end: 16px;
        width: calc(var(--seka-avatar-size) + 6px);
        margin: 0;
    }

    #chat .mes .avatar {
        margin: 2px;
    }

    #chat .mes_block {
        padding-left: 5px;
    }

    #chat .mes[is_user="false"]:not([is_system="true"]) .mes_block {
        flex: 1 1 100%;
        width: 100%;
        max-width: 100%;
        padding-inline: 5px;
    }

    #chat .mes[is_user="false"]:not([is_system="true"]) .ch_name {
        padding-inline-end: calc(var(--seka-avatar-size) + 28px);
    }

    #chat .ch_name {
        min-height: 24px;
        padding-bottom: 5px;
    }

    #chat .name_text {
        font-size: 1rem;
    }

    #chat .mes_text,
    #chat .mes_reasoning {
        font-size: 0.98rem;
        line-height: 1.78;
    }

    #chat .mes_text {
        padding: 8px 2px 10px;
    }

    #send_form {
        border-radius: 0 0 var(--seka-radius-medium) var(--seka-radius-medium);
    }

    #options_button,
    #extensionsMenuButton,
    #send_but,
    #mes_continue,
    #mes_impersonate,
    #send_form .mes_stop {
        min-width: 40px;
        min-height: 40px;
    }

    #left-nav-panel,
    #rm_api_block,
    #AdvancedFormatting,
    #WorldInfo,
    #user-settings-block,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #right-nav-panel {
        width: calc(100dvw - 10px);
        min-width: 0;
        max-width: calc(100dvw - 10px);
        border-radius: var(--seka-radius-medium);
        padding: 8px;
    }

    #user-settings-block-content,
    #PersonaManagement > .flex-container,
    #right-nav-panel .flex-container {
        min-width: 0;
    }

    .popup {
        width: min(94dvw, 760px);
        max-width: 94dvw;
        max-height: 88dvh;
        border-radius: var(--seka-radius-medium);
    }

    .popup .popup-controls {
        gap: 8px;
    }

    #completion_prompt_manager_popup {
        width: calc(100dvw - 10px);
        min-width: 0;
        max-width: calc(100dvw - 10px);
        border-radius: var(--seka-radius-medium);
    }

    #toast-container {
        width: calc(100dvw - 16px);
        max-width: calc(100dvw - 16px);
        margin-inline: 8px;
    }

    #toast-container > .toast {
        width: 100%;
        margin-inline: 0;
    }
}

@media screen and (max-width: 430px) {
    #send_form {
        display: flex;
        flex-flow: column nowrap;
        align-items: stretch;
    }

    #send_form > #file_form,
    #send_form > #qr--bar,
    #send_form > #nonQRFormItems {
        width: 100%;
        min-width: 0;
    }

    #send_form > #qr--bar {
        order: 1;
        flex: 0 0 auto;
    }

    #send_form > #nonQRFormItems {
        order: 2;
        display: grid;
        grid-template-columns: auto minmax(0, 1fr) auto;
        align-items: center;
        column-gap: 4px;
    }

    #nonQRFormItems > #leftSendForm,
    #nonQRFormItems > #rightSendForm {
        display: flex;
        flex-flow: row nowrap;
        align-items: center;
        width: auto;
        min-width: 0;
    }

    #nonQRFormItems > #leftSendForm {
        grid-column: 1;
    }

    #nonQRFormItems > #send_textarea {
        grid-column: 2;
        width: 100%;
        min-width: 0;
        max-width: none;
        margin: 0;
        font-size: var(--mainFontSize);
    }

    #nonQRFormItems > #rightSendForm {
        grid-column: 3;
    }
}

/* ===== src/fallback.css ===== */
/* Seka / capability and motion fallbacks. */
@supports not selector(:has(*)) {
    :where(
        #ai-config-button,
        #sys-settings-button,
        #advanced-formatting-button,
        #WI-SP-button,
        #user-settings-button,
        #backgrounds-button,
        #extensions-settings-button,
        #persona-management-button,
        #rightNavHolder
    ) > .drawer-toggle .drawer-icon.openIcon {
        color: #243a5b;
        box-shadow: inset 0 -3px var(--seka-coral);
    }
}

@media (prefers-reduced-motion: reduce) {
    #chat .mes_button,
    #chat .extraMesButtons > div,
    #chat .mes_edit_buttons .menu_button,
    #top-settings-holder .drawer-toggle,
    #send_form #options_button,
    #send_form #extensionsMenuButton,
    #send_form #send_but,
    #send_form #mes_stop {
        transition-duration: 0.01ms;
        transform: none;
    }
}
